// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title VulnerableVault
/// @notice An ETH vault that credits the withdrawal *after* sending the funds.
/// @dev The bug is the ordering on lines marked INTERACTION / EFFECT. `balanceOf`
///      is still the pre-withdrawal amount while control is handed to the
///      recipient, so a contract recipient can call `withdraw` again from its
///      receive hook and pass the `require` a second time.
///
///      This is The DAO (June 2016, ~3.6M ETH) reduced to its essential shape.
contract VulnerableVault {
    mapping(address => uint256) public balanceOf;

    function deposit() external payable {
        balanceOf[msg.sender] += msg.value;
    }

    function withdraw() external {
        uint256 bal = balanceOf[msg.sender];
        require(bal > 0, "nothing to withdraw");

        // INTERACTION — hands control to msg.sender before any state update.
        (bool ok,) = msg.sender.call{value: bal}("");
        require(ok, "transfer failed");

        // EFFECT — reached only after the callee returns. Too late.
        balanceOf[msg.sender] = 0;
    }
}

/// @title FixedVault
/// @notice The same vault with checks-effects-interactions restored and a
///         reentrancy guard as defence in depth.
/// @dev Either fix alone stops the attack. Both are present because CEI is easy
///      to break during a later refactor, and the guard is a cheap invariant that
///      survives one.
contract FixedVault {
    mapping(address => uint256) public balanceOf;

    uint256 private constant _UNLOCKED = 1;
    uint256 private constant _LOCKED = 2;
    uint256 private _status = _UNLOCKED;

    modifier nonReentrant() {
        require(_status == _UNLOCKED, "reentrant call");
        _status = _LOCKED;
        _;
        _status = _UNLOCKED;
    }

    function deposit() external payable {
        balanceOf[msg.sender] += msg.value;
    }

    function withdraw() external nonReentrant {
        uint256 bal = balanceOf[msg.sender];
        require(bal > 0, "nothing to withdraw");

